namespace sv_871a8a6d114d486bb3a4ec0433693e80.Client.Models;

public sealed class ShipmentDetails
{
    public required string TrackingNumber { get; init; }
    public required string Status { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset EstimatedDelivery { get; init; }
    public required IReadOnlyList<StatusUpdate> StatusUpdates { get; init; }
}

public sealed class StatusUpdate
{
    public required string Description { get; init; }
    public required string Location { get; init; }
    public required DateTimeOffset Timestamp { get; init; }
}

using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Models;

namespace sv_871a8a6d114d486bb3a4ec0433693e80.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Models;

namespace sv_871a8a6d114d486bb3a4ec0433693e80.Client.Services;

/// <summary>
/// HttpClient-based implementation used when running on WebAssembly.
/// Calls back to the server API to fetch shipment data.
/// </summary>
public sealed class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Models;
using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Services;

namespace sv_871a8a6d114d486bb3a4ec0433693e80.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 22, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Package picked up",
                    Location = "New York, NY",
                    Timestamp = new DateTimeOffset(2026, 6, 16, 9, 30, 0, TimeSpan.FromHours(-4))
                },
                new StatusUpdate
                {
                    Description = "Departed sorting facility",
                    Location = "Newark, NJ",
                    Timestamp = new DateTimeOffset(2026, 6, 17, 2, 15, 0, TimeSpan.FromHours(-4))
                },
                new StatusUpdate
                {
                    Description = "Arrived at regional hub",
                    Location = "Chicago, IL",
                    Timestamp = new DateTimeOffset(2026, 6, 18, 14, 45, 0, TimeSpan.FromHours(-5))
                }
            ]
        },
        ["PKG-002"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 18, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Package picked up",
                    Location = "Seattle, WA",
                    Timestamp = new DateTimeOffset(2026, 6, 14, 10, 0, 0, TimeSpan.FromHours(-7))
                },
                new StatusUpdate
                {
                    Description = "In transit",
                    Location = "Portland, OR",
                    Timestamp = new DateTimeOffset(2026, 6, 15, 6, 20, 0, TimeSpan.FromHours(-7))
                },
                new StatusUpdate
                {
                    Description = "Out for delivery",
                    Location = "San Francisco, CA",
                    Timestamp = new DateTimeOffset(2026, 6, 17, 8, 0, 0, TimeSpan.FromHours(-7))
                },
                new StatusUpdate
                {
                    Description = "Delivered — left at front door",
                    Location = "San Francisco, CA",
                    Timestamp = new DateTimeOffset(2026, 6, 17, 14, 32, 0, TimeSpan.FromHours(-7))
                }
            ]
        },
        ["PKG-003"] = new ShipmentDetails
        {
            TrackingNumber = "PKG-003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTimeOffset(2026, 6, 25, 18, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates =
            [
                new StatusUpdate
                {
                    Description = "Label created",
                    Location = "Dallas, TX",
                    Timestamp = new DateTimeOffset(2026, 6, 19, 7, 0, 0, TimeSpan.FromHours(-5))
                }
            ]
        }
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate a slow backend call
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

