@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger

@using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Models
@using sv_871a8a6d114d486bb3a4ec0433693e80.Client.Services

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h1>Shipment Tracker</h1>

@if (isLoading)
{
    <p>Loading shipment <strong>@TrackingNumber</strong>…</p>
}
else if (errorMessage is not null)
{
    <div>
        <p>@errorMessage</p>
        <button @onclick="RetryAsync">Retry</button>
    </div>
}
else if (shipment is null)
{
    <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
}
else
{
    <dl>
        <dt>Tracking Number</dt>
        <dd>@shipment.TrackingNumber</dd>
        <dt>Status</dt>
        <dd>@shipment.Status</dd>
        <dt>Location</dt>
        <dd>@shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h2>Status Updates</h2>
    @if (shipment.StatusUpdates.Count == 0)
    {
        <p>No status updates yet.</p>
    }
    else
    {
        <ul>
            @foreach (var update in shipment.StatusUpdates)
            {
                <li @key="update.Timestamp">
                    <strong>@update.Timestamp.ToString("g")</strong> —
                    @update.Description (@update.Location)
                </li>
            }
        </ul>
    }
}

@code {
    [Parameter] public string TrackingNumber { get; set; } = "";

    private string currentTrackingNumber = "";
    private ShipmentDetails? shipment;
    private bool isLoading;
    private string? errorMessage;
    private CancellationTokenSource? cts;

    protected override async Task OnParametersSetAsync()
    {
        if (string.Equals(currentTrackingNumber, TrackingNumber, StringComparison.Ordinal))
        {
            return;
        }

        currentTrackingNumber = TrackingNumber;
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        cts?.Cancel();
        cts?.Dispose();
        cts = new CancellationTokenSource();
        var token = cts.Token;

        shipment = null;
        errorMessage = null;
        isLoading = true;

        try
        {
            shipment = await ShipmentService.GetShipmentAsync(currentTrackingNumber, token);
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Load was cancelled (navigation or disposal) — nothing to do.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", currentTrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", currentTrackingNumber);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", currentTrackingNumber);
            errorMessage = "Something went wrong loading shipment details. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public ValueTask DisposeAsync()
    {
        cts?.Cancel();
        cts?.Dispose();
        return ValueTask.CompletedTask;
    }
}

